// Generated by Skyramp v1.3.44 on 2026-09-12
// Scenario: /home/runner/work/eval-linkwarden/eval-linkwarden/apps/web/e2e/scenario_preferences_session_cookie_contract.json
//
// Contract for GET /api/v1/users/me/preferences (added by this PR):
//   - a valid NextAuth session cookie reads the caller's preference settings with 200
//   - a request with no credential is refused with 401
//   - a non-GET method is refused with 405
// The session this test creates is revoked in its last steps.

// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getResponseValue, checkSchema, uniqueSuffix } from '@skyramp/skyramp';
import {
    SESSION_COOKIE,
    createSession,
    getUserPreferences,
    postUserPreferences,
    getTokens,
    deleteToken,
} from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

// Enum values declared in packages/prisma/schema.prisma, which this PR did not change.
const LINKS_ROUTE_TO = ["ORIGINAL", "PDF", "READABLE", "MONOLITH", "SCREENSHOT", "DETAILS"];
const THEMES = ["dark", "light", "auto"];

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();

    // Unique per run so a re-run does not collide with the session a previous run left behind.
    const sessionName = uniqueSuffix("skyramp-prefs-contract");

    // Step 1 — create a NextAuth session for the test user.
    const sessionPostResponse = await createSession(client, URL_localhost, sessionName);

    expect(sessionPostResponse.statusCode, 'status code').toBe(200);

    const sessionToken = getResponseValue(sessionPostResponse, "response.token");
    expect(typeof sessionToken, 'session token is a string').toBe("string");
    expect(sessionToken.length, 'session token is not empty').toBeGreaterThan(0);
    expect(sessionToken, 'session token is a JWE the NextAuth secret produced').toMatch(/^ey[\w-]+\.{2}/);

    const sessionAuth = {cookies: {[SESSION_COOKIE]: sessionToken}};

    // Steps 2-6. The revocation in the finally block runs even when an assertion above
    // fails, so this test never leaves a live session behind.
    try {
        // Step 2 — read preferences with the session cookie. This is the behaviour under test.
        const preferencesGetResponse = await getUserPreferences(client, URL_localhost, sessionAuth, 200);

        expect(preferencesGetResponse.statusCode, 'status code').toBe(200);

        const preferences = getResponseValue(preferencesGetResponse, "response");
        expect(preferences, 'preferences payload is present').not.toBeNull();

        // Every selected field is PRESENT with its declared type. A value read back cannot tell a
        // null field from a missing one, so the shape is checked against an example body.
        expect(checkSchema(preferencesGetResponse, `{
            "response": {
                "id": "number",
                "linksRouteTo": "string",
                "preventDuplicateLinks": "boolean",
                "archiveAsScreenshot": "boolean",
                "archiveAsMonolith": "boolean",
                "archiveAsPDF": "boolean",
                "archiveAsWaybackMachine": "boolean",
                "locale": "string",
                "theme": "string"
            }
        }`), 'the 200 payload carries every preference field the handler selects').toBe(true);

        // Every field the handler selects is present and carries its declared type.
        expect(typeof getResponseValue(preferencesGetResponse, "response.id"), 'id is a number').toBe("number");
        expect(getResponseValue(preferencesGetResponse, "response.id"), 'id is a real user id').toBeGreaterThan(0);
        expect(LINKS_ROUTE_TO, 'linksRouteTo is a LinksRouteTo value')
            .toContain(getResponseValue(preferencesGetResponse, "response.linksRouteTo"));
        expect(THEMES, 'theme is a Theme value')
            .toContain(getResponseValue(preferencesGetResponse, "response.theme"));
        expect(typeof getResponseValue(preferencesGetResponse, "response.locale"), 'locale is a string').toBe("string");
        expect(getResponseValue(preferencesGetResponse, "response.locale"), 'locale is a BCP-47 language tag').toMatch(/^[a-z]{2}(-[A-Za-z0-9]+)*$/);
        for (const flag of [
            "preventDuplicateLinks",
            "archiveAsScreenshot",
            "archiveAsMonolith",
            "archiveAsPDF",
            "archiveAsWaybackMachine",
        ]) {
            expect(typeof getResponseValue(preferencesGetResponse, `response.${flag}`), `${flag} is a boolean`).toBe("boolean");
        }

        // The endpoint is documented as returning preference data only — it must not leak credentials.
        expect(getResponseValue(preferencesGetResponse, "response.password"), 'password is not exposed').toBeNull();
        expect(getResponseValue(preferencesGetResponse, "response.email"), 'email is not exposed').toBeNull();

        // Step 3 — no credential at all is refused.
        const preferencesGet1Response = await getUserPreferences(client, URL_localhost, {}, 401);

        expect(preferencesGet1Response.statusCode, 'status code').toBe(401);
        expect(getResponseValue(preferencesGet1Response, "response"), 'uncredentialed request is told it is unauthorized').toBe("Unauthorized.");
        expect(getResponseValue(preferencesGet1Response, "response.linksRouteTo"), 'no preference data leaks on 401').toBeNull();

        // Step 4 — a non-GET method is refused, even with a valid session cookie.
        const preferencesPostResponse = await postUserPreferences(client, URL_localhost, sessionAuth, 405);

        expect(preferencesPostResponse.statusCode, 'status code').toBe(405);
        expect(getResponseValue(preferencesPostResponse, "response"), 'POST is refused as method not allowed').toBe("Method not allowed.");
        expect(getResponseValue(preferencesPostResponse, "response.linksRouteTo"), 'no preference data leaks on 405').toBeNull();
    } finally {
        // Step 5 — locate the session this test created, by its unique name.
        const tokensGetResponse = await getTokens(client, URL_localhost, sessionAuth, 200);

        expect(tokensGetResponse.statusCode, 'status code').toBe(200);

        const tokens = getResponseValue(tokensGetResponse, "response");
        expect(Array.isArray(tokens), 'token list is an array').toBe(true);
        const createdSession = tokens.find((t: any) => t.name === sessionName);
        expect(createdSession, `the session named ${sessionName} is listed`).toBeDefined();
        expect(createdSession.isSession, 'the credential created by POST /api/v1/session is a session').toBe(true);
        expect(createdSession.name, 'the listed session carries the name this test sent').toBe(sessionName);
        expect(createdSession.id, 'the listed session has a real id').toBeGreaterThan(0);
        expect(createdSession.expires, 'the listed session carries an ISO expiry').toMatch(/^\d{4}-\d{2}-\d{2}T/);

        // Step 6 — revoke the session this test created, so the run leaves no usable credential behind.
        const tokensTokensDeleteResponse = await deleteToken(client, URL_localhost, createdSession.id, sessionAuth, 200);

        expect(tokensTokensDeleteResponse.statusCode, 'status code').toBe(200);
        expect(getResponseValue(tokensTokensDeleteResponse, "response.revoked"), 'the session is revoked').toBe(true);
        expect(getResponseValue(tokensTokensDeleteResponse, "response.id"), 'the revoked record is the one this test created').toBe(createdSession.id);
        expect(getResponseValue(tokensTokensDeleteResponse, "response.name"), 'the revoked record carries the name this test sent').toBe(sessionName);
        expect(getResponseValue(tokensTokensDeleteResponse, "response.isSession"), 'the revoked record is the session, not a personal access token').toBe(true);
    }
});
